-- Ads content is never shown to new installs from Gujarat or Maharashtra.
--
-- Hard-coded rule: an install whose request comes from an IP address located
-- in Gujarat (GJ) or Maharashtra (MH) is flagged once, when the install row is
-- first created. A user whose first install is flagged is treated as organic:
-- no ads-audience content or ads previews (not even with admin approval), but
-- organic content as usual. Attribution itself (source_of, admin reports,
-- Meta events) is left as it was.
--
-- Only new installs: rows that existed before this migration keep
-- geo_blocked = false, and the flag is never recomputed later.
--
-- The client IP is Cloudflare's cf-connecting-ip header, which the client
-- cannot set itself. Location is approximate: IP ranges with no known state
-- (most mobile IPv6) are let through.
--
-- IP ranges: GeoLite2 City data by MaxMind (https://www.maxmind.com), via
-- ip-location-db, June 2026 snapshot; India rows for the two states only,
-- adjacent ranges merged.

create table public.geo_blocked_ranges (
  start_ip inet not null,
  end_ip   inet not null,
  state    text not null check (state in ('GJ', 'MH'))
);
create index geo_blocked_ranges_start_idx on public.geo_blocked_ranges (start_ip);
alter table public.geo_blocked_ranges enable row level security;
revoke all on public.geo_blocked_ranges from public, anon, authenticated;

alter table public.installs
  add column geo_state text,
  add column geo_blocked boolean not null default false;

-- State (GJ / MH) of the current request's IP, or null when it isn't in one
-- of the two states or can't be read.
create or replace function public.request_geo_state()
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_ip inet;
  v_state text;
begin
  begin
    v_ip := (nullif(current_setting('request.headers', true), '')::json ->> 'cf-connecting-ip')::inet;
  exception when others then
    return null;
  end;
  if v_ip is null then return null; end if;
  select g.state into v_state
    from (select * from public.geo_blocked_ranges r
           where r.start_ip <= v_ip
           order by r.start_ip desc
           limit 1) g
   where g.end_ip >= v_ip and family(g.start_ip) = family(v_ip);
  return v_state;
end $$;
revoke execute on function public.request_geo_state() from public, anon, authenticated;

-- Is the current user's first install flagged?
create or replace function public.geo_blocked()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.user_attribution ua
      join public.installs i on i.install_id = ua.first_touch_install_id
     where ua.user_id = auth.uid() and i.geo_blocked)
$$;
revoke execute on function public.geo_blocked() from public;
grant execute on function public.geo_blocked() to anon, authenticated;

-- Same as before, plus the location flag on the first insert only.
create or replace function public.record_install(
  p_install_id uuid,
  p_referrer_status text,
  p_referrer text default null,
  p_click_ts timestamptz default null,
  p_install_ts timestamptz default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_source text := public.parse_source(p_referrer_status, p_referrer);
  v_geo text := public.request_geo_state();
begin
  insert into public.installs as i (
    install_id, referrer_status, raw_referrer, source,
    utm_source, utm_medium, utm_campaign, utm_content, utm_term,
    click_ts, install_ts, geo_state, geo_blocked)
  values (
    p_install_id, p_referrer_status, p_referrer, v_source,
    public.referrer_param(p_referrer, 'utm_source'),
    public.referrer_param(p_referrer, 'utm_medium'),
    public.referrer_param(p_referrer, 'utm_campaign'),
    public.referrer_param(p_referrer, 'utm_content'),
    public.referrer_param(p_referrer, 'utm_term'),
    p_click_ts, p_install_ts, v_geo, v_geo is not null)
  on conflict (install_id) do update
     set referrer_status = excluded.referrer_status,
         raw_referrer    = excluded.raw_referrer,
         source          = excluded.source,
         utm_source      = excluded.utm_source,
         utm_medium      = excluded.utm_medium,
         utm_campaign    = excluded.utm_campaign,
         utm_content     = excluded.utm_content,
         utm_term        = excluded.utm_term,
         click_ts        = excluded.click_ts,
         install_ts      = excluded.install_ts,
         updated_at      = now()
   where i.referrer_status not in ('ok', 'apk')
     and excluded.referrer_status in ('ok', 'apk');

  perform public.attribute_user(p_install_id);
  return (select source from public.installs where install_id = p_install_id);
end $$;

-- Flagged users never get ads access, approved or not.
create or replace function public.has_ads_access()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select not public.geo_blocked()
     and (public.source_of(auth.uid()) = 'ads'
          or exists (select 1 from public.profiles
                      where id = auth.uid() and ads_access_status = 'approved'))
$$;

-- Flagged users see organic content like organic users.
create or replace function public.can_see(p_audience public.audience)
returns boolean
language sql
stable
set search_path = ''
as $$
  select public.is_admin() or case p_audience
    when 'all'     then true
    when 'organic' then public.user_source() = 'organic' or public.geo_blocked()
    when 'ads'     then public.has_ads_access()
  end
$$;

-- The app sees a flagged user as organic.
create or replace function public.my_status()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'user_id',        p.id,
    'display_name',   p.display_name,
    'avatar_url',     p.avatar_url,
    'is_guest',       p.is_guest,
    'source',         case when public.geo_blocked() then 'organic' else public.source_of(p.id) end,
    'has_ads_access', public.has_ads_access(),
    'is_premium',     public.is_premium_user(),
    'plan_name',      cur.name,
    'plan_ends_at',   cur.ends_at,
    'used_bytes',     p.used_bytes,
    'quota_bytes',    public.quota_bytes(p.id),
    'open_request',   (select pl.name from public.plan_requests r join public.plans pl on pl.id = r.plan_id
                        where r.user_id = p.id and r.status = 'open' limit 1),
    'free_mode',      public.free_mode(),
    'access_status',  p.ads_access_status)
    from public.profiles p
    left join lateral (
      select pl.name, s.ends_at from public.subscriptions s join public.plans pl on pl.id = s.plan_id
       where s.user_id = p.id and now() between s.starts_at and s.ends_at
       order by s.ends_at desc limit 1) cur on true
   where p.id = auth.uid()
$$;

-- Flagged users can't queue an access request (approval would not apply).
create or replace function public.request_full_access()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_status public.ads_access_status;
begin
  if auth.uid() is null then raise exception 'please log in'; end if;
  if exists (select 1 from public.profiles where id = auth.uid() and is_guest) then
    raise exception 'please log in';
  end if;
  if public.has_ads_access() then return 'approved'; end if;
  if not public.geo_blocked() then
    update public.profiles
       set ads_access_status = 'pending', updated_at = now()
     where id = auth.uid() and ads_access_status = 'none';
  end if;
  select ads_access_status into v_status from public.profiles where id = auth.uid();
  return v_status::text;
end $$;

